document.getElementById('login').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button'),error=document.getElementById('error');button.disabled=true;error.textContent='';try{const r=await fetch('/api/login',{method:'POST',headers:{'content-type':'application/json','x-ic-request':'1'},body:JSON.stringify({username:document.getElementById('username').value,password:document.getElementById('password').value})});const data=await r.json();if(!r.ok)throw Error(data.error||'Chưa đăng nhập được.');const studyLink=location.hash;if(studyLink)location.replace('/study'+studyLink);else location.assign(data.user.role==='admin'?'/admin':'/study')}catch(e){error.textContent=e.message;button.disabled=false}});
